use dlm_network_proof::*;
fn fixture()->(NetworkSpecIR,NetworkExecutableIR,NetworkProofIR){let certificate=NetworkCertificate::from_text(include_str!("../../dlm_core/tests/native_hosts/generated/state_session.dlm.nproof"),NetworkBudget::default()).unwrap();(NetworkSpecIR::from_bytes(&certificate.descriptor).unwrap(),NetworkExecutableIR::from_bytes(&certificate.executable).unwrap(),certificate.proof)}
fn check(spec:&NetworkSpecIR,machine:&NetworkExecutableIR,proof:&NetworkProofIR)->Result<NetworkAudit>{check_network_proof(spec,machine,1,proof,NetworkBudget::default())}
#[test]
fn fixed_rules_accept_real_graph_and_keep_native_obligations_pending(){let(s,m,p)=fixture();let r=check(&s,&m,&p).unwrap();assert_eq!(r.model_verified,416);assert_eq!(r.runtime_pending,431);assert!(r.work>0 && r.work<200000);assert!(r.assumptions.iter().any(|s|s.contains("GnuTLS")));assert!(r.json().contains("\"native_correctness_proved\":false"));}
#[test]
fn guards_resource_balance_determinism_lifecycle_and_cleanup_cannot_be_forged(){let(s,m,p)=fixture();for mode in 0..12{let mut bad=m.clone();match mode{0=>bad.transitions[1].0[4]=999,1=>bad.states[6].0[2]=1,2=>bad.transitions.push(bad.transitions[0].clone()),3=>bad.transitions[1].0[5]=1,4=>bad.states[3].0[3]=0,5=>bad.transitions[3].0[1]=11,6=>bad.transitions[0].0[3]=1,7=>bad.transitions[0].0[1]=3,8=>bad.states[1].0[2]=2,9=>bad.states[0].0[3]=1,10=>bad.transitions[1].0[4]=4,_=>bad.transitions[0].0[7]=2}assert!(check(&s,&bad,&p).is_err(),"accepted mode {mode}");}}
#[test]
fn witness_and_budget_failures_never_become_proofs(){let(s,m,p)=fixture();let mut bad=p.clone();bad.ranks[3]=0;assert!(check(&s,&m,&bad).is_err());bad=p.clone();bad.reachable=0;assert!(check(&s,&m,&bad).is_err());bad=p.clone();bad.properties=2047;assert!(check(&s,&m,&bad).is_err());let result=check_network_proof(&s,&m,1,&p,NetworkBudget{max_work:0,..NetworkBudget::default()}).unwrap_err();assert_eq!(result.kind,ErrorKind::UnknownWithinBudget);}
#[test]
fn custom_active_states_and_authentication_contracts_are_checked_by_the_same_rules(){let(mut s,mut m,mut p)=fixture();m.states.push(NetworkStateIR([40,3,1,1,0]));let send=m.transitions.iter_mut().find(|t|t.0[0]==4 && t.0[1]==4 && t.0[2]==1).unwrap();send.0[4]=40;let additions=m.transitions.iter().filter(|t|t.0[0]==4 && matches!(t.0[1],6..=10)).cloned().collect::<Vec<_>>();for mut t in additions{t.0[0]=40;m.transitions.push(t);}p.reachable=255;p.ranks.push(4);check(&s,&m,&p).unwrap();s.words[25]=1;s.words[26]=1;p.properties|=64;let r=check(&s,&m,&p).unwrap();assert_eq!(r.model_verified,480);assert_ne!(r.runtime_pending&1024,0);let send=m.transitions.iter_mut().find(|t|t.0[0]==4&&t.0[1]==4&&t.0[2]==1).unwrap();send.0[7]=0;assert!(check(&s,&m,&p).is_err());}
#[test]
fn canonical_ir_and_certificate_roundtrip_reject_all_truncated_prefixes(){let(s,m,_)=fixture();for data in [s.to_bytes(),m.to_bytes()]{for prefix in 0..data.len(){let result=if data.starts_with(b"DNS1"){NetworkSpecIR::from_bytes(&data[..prefix]).map(|_|())}else{NetworkExecutableIR::from_bytes(&data[..prefix]).map(|_|())};assert!(result.is_err(),"accepted truncated prefix {prefix}");}}assert_eq!(NetworkSpecIR::from_bytes(&s.to_bytes()).unwrap(),s);assert_eq!(NetworkExecutableIR::from_bytes(&m.to_bytes()).unwrap(),m);let source=include_str!("../../dlm_core/tests/native_hosts/generated/state_session.dlm");let commented=format!("/* outer /* nested */ still outer */\n{source}");source_matches(&commented,&s,&m,1,"generated.state_session","State").unwrap();assert!(source_matches(&format!("/* outer /* nested */ {source}"),&s,&m,1,"generated.state_session","State").is_err());let text=include_str!("../../dlm_core/tests/native_hosts/generated/state_session.dlm.nproof");let proof=NetworkCertificate::from_text(text,NetworkBudget::default()).unwrap();assert_eq!(NetworkCertificate::from_text(&proof.to_text(),NetworkBudget::default()).unwrap(),proof);assert!(NetworkCertificate::from_text(&(text.to_owned()+"minor 1\n"),NetworkBudget::default()).is_err());}
#[test]
fn hostile_ir_mutations_are_bounded_and_never_panic(){let(s,m,p)=fixture();let mut random=143u32;for original in [s.to_bytes(),m.to_bytes()]{for _ in 0..3000{let mut bytes=original.clone();random=random.wrapping_mul(1664525).wrapping_add(1013904223);let index=random as usize%bytes.len();random=random.wrapping_mul(1664525).wrapping_add(1013904223);bytes[index]^=1<<(random%8);if bytes.starts_with(b"DNS1"){if let Ok(schema)=NetworkSpecIR::from_bytes(&bytes){let _=check(&schema,&m,&p);}}else if let Ok(machine)=NetworkExecutableIR::from_bytes(&bytes){let _=check(&s,&machine,&p);}}}}
#[test]
fn digest_matches_independent_standard_vectors(){assert_eq!(sha256(b""),"e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855");assert_eq!(sha256(b"abc"),"ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");assert_eq!(sha256(&vec![b'a';1_000_000]),"cdc76e5c9914fb9281a1c7e284d73e67f1809a48a497200e046d39ccc7112cd0");}
